CustomField.formula:
IF( ISBLANK(Segment_Date__c), "",
/* Years */ IF( YEAR(Today()) - YEAR(Segment_Date__c) - IF( OR( MONTH(Today()) < MONTH(Segment_Date__c), AND( MONTH(Today()) = MONTH(Segment_Date__c), DAY(Today()) < DAY(Segment_Date__c) ) ), 1, 0 ) > 0,
TEXT( YEAR(Today()) - YEAR(Segment_Date__c) - IF( OR( MONTH(Today()) < MONTH(Segment_Date__c), AND( MONTH(Today()) = MONTH(Segment_Date__c), DAY(Today()) < DAY(Segment_Date__c) ) ), 1, 0 ) ) & " Years ", "" ) &
/* Months */ IF( MOD( (YEAR(Today()) - YEAR(Segment_Date__c)) * 12 + MONTH(Today()) - MONTH(Segment_Date__c) - IF(DAY(Today()) < DAY(Segment_Date__c), 1, 0), 12 ) > 0,
TEXT( MOD( (YEAR(Today()) - YEAR(Segment_Date__c)) * 12 + MONTH(Today()) - MONTH(Segment_Date__c) - IF(DAY(Today()) < DAY(Segment_Date__c), 1, 0), 12 ) ) & " Months ", "" ) &
/* Days */ TEXT( IF( DAY(Today()) >= DAY(Segment_Date__c), DAY(Today()) - DAY(Segment_Date__c), DAY(DATE(YEAR(Today()), MONTH(Today()), 1) - 1) + DAY(Today()) - DAY(Segment_Date__c) ) ) & " Days" )
